from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = set()
        # book_id -> (user, borrow_day)
        self.borrowed = {}
        # user -> total unpaid fines
        self.fines = {}
        # user -> number of books currently held
        self.held = {}

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Unknown book: {book_id}")
        if book_id in self.borrowed:
            raise ValueError(f"Book already borrowed: {book_id}")
        if self.fines.get(user, 0.0) > 0 and self.held.get(user, 0) >= 1:
            raise ValueError(
                f"User {user} has unpaid fines and already holds a book"
            )
        self.borrowed[book_id] = (user, day)
        self.held[user] = self.held.get(user, 0) + 1

    def _count_delay_days(self, start: date, end: date) -> int:
        """Count weekdays (Mon-Fri) strictly after `start` up to and including `end`."""
        if end <= start:
            return 0
        days = 0
        current = start + timedelta(days=1)
        while current <= end:
            if current.weekday() < 5:  # Monday=0 ... Friday=4
                days += 1
            current += timedelta(days=1)
        return days

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.borrowed:
            raise ValueError(f"Book is not currently borrowed: {book_id}")
        borrower, borrow_day = self.borrowed[book_id]
        if borrower != user:
            raise ValueError(
                f"Book {book_id} is not borrowed by {user}"
            )

        due = borrow_day + timedelta(days=self.loan_days)
        delay_days = self._count_delay_days(due, day)
        fine = delay_days * self.daily_fine

        del self.borrowed[book_id]
        self.held[user] = self.held.get(user, 1) - 1
        if fine > 0:
            self.fines[user] = self.fines.get(user, 0.0) + fine
        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        if user in self.fines:
            self.fines[user] = 0.0
